                            protectionContext: Factory_Flow.ProtectionContext => B,
                            snapshotToOutcome: Factory_Flow.FlowSnapshot => B,
                            snapshotToStatus: Factory_Flow.FlowSnapshot => B,
                            lineCommand: Factory_Flow.LineFlowCommand => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val contextToReadinessValue: Factory_Flow.FlowContext = get_contextToReadiness().get
    if(!contextToReadiness(contextToReadinessValue)) {
      testFailures = testFailures :+ st"'contextToReadiness' did not match expected: value of the outgoing data port is ${contextToReadinessValue}"
    }
    val contextToOutcomeValue: Factory_Flow.FlowContext = get_contextToOutcome().get
    if(!contextToOutcome(contextToOutcomeValue)) {
      testFailures = testFailures :+ st"'contextToOutcome' did not match expected: value of the outgoing data port is ${contextToOutcomeValue}"
    }
    val protectionContextValue: Factory_Flow.ProtectionContext = get_protectionContext().get
    if(!protectionContext(protectionContextValue)) {
      testFailures = testFailures :+ st"'protectionContext' did not match expected: value of the outgoing data port is ${protectionContextValue}"
    }
    val snapshotToOutcomeValue: Factory_Flow.FlowSnapshot = get_snapshotToOutcome().get
    if(!snapshotToOutcome(snapshotToOutcomeValue)) {
      testFailures = testFailures :+ st"'snapshotToOutcome' did not match expected: value of the outgoing data port is ${snapshotToOutcomeValue}"
    }
    val snapshotToStatusValue: Factory_Flow.FlowSnapshot = get_snapshotToStatus().get
    if(!snapshotToStatus(snapshotToStatusValue)) {
      testFailures = testFailures :+ st"'snapshotToStatus' did not match expected: value of the outgoing data port is ${snapshotToStatusValue}"
    }
    val lineCommandValue: Factory_Flow.LineFlowCommand = get_lineCommand().get
    if(!lineCommand(lineCommandValue)) {
      testFailures = testFailures :+ st"'lineCommand' did not match expected: value of the outgoing data port is ${lineCommandValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


